 results[i]={'mathdb_id':int(i),'title':r['title'],'literal_statement':r['statement'],'source_url':r['source_url'],'provenance':{k:v[k] for k in ('chunk','line','chunk_sha256','raw_sha256')},'outcome':outcome,'review_depth':depth,'mathematical_attempts_and_exact_coverage':attempt,'remaining_obligation':gap,'lean_cost':cost,'credit_risk':risk,'source_versions':versions[i],'source_receipts':receipts,'literature_search_evidence':'sources/web-search-01.json through web-search-12.json; bounded targeted title/author/citing-work searches, not exhaustive citation-graph traversal.','historical_screen':'outputs/history-exact-id-hits.txt and outputs/history-title-hits.txt; inherited family warnings in TASK.txt.','registry_screen':'outputs/registry-screen.json','version_of_record_limit':'Publisher body is only considered read where explicitly stated. Other DOI/metadata/author-manuscript routes are not blanket version-of-record clearance.','lean_endpoint':None,'nominated':False,'accepted_credit':0}
